-- Raxi HQ v0.9: private, owner-scoped persistent schema.
-- IMPORTANT: data is not yet imported, agents are not connected.
create table public.raxi_workspaces (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null default auth.uid() references auth.users(id), slug text not null check(length(slug) between 2 and 64 and slug ~ '^[a-z0-9-]+$'), name text not null check(length(name) between 2 and 160), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_user_id,slug));
alter table public.raxi_workspaces enable row level security;
create table public.raxi_ideas (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, external_id text not null check(length(external_id) between 1 and 128), kind text not null check(kind in ('DRAFT','PROPOSAL')), title text not null check(length(title) between 1 and 120), status text not null check(status in ('DRAFT','PROPOSED','UNDER_REVIEW','APPROVED_FOR_HQ','REJECTED','ARCHIVED','SENT_TO_HQ')), source text not null, summary text, priority text, payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id), unique(workspace_id,external_id));
alter table public.raxi_ideas enable row level security;
create table public.raxi_idea_evidence (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, idea_id uuid not null, external_id text, kind text not null, label text not null, source_ref text, payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), captured_at timestamptz, created_at timestamptz not null default now(), foreign key(workspace_id,idea_id) references public.raxi_ideas(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,idea_id,external_id));
alter table public.raxi_idea_evidence enable row level security;
create table public.raxi_idea_handoffs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, idea_id uuid not null, sent_at timestamptz not null, payload jsonb not null check(jsonb_typeof(payload)='object'), created_at timestamptz not null default now(), foreign key(workspace_id,idea_id) references public.raxi_ideas(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,idea_id));
alter table public.raxi_idea_handoffs enable row level security;
create table public.raxi_campaigns (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, external_id text not null check(length(external_id) between 1 and 128), source_idea_id uuid not null, title text not null check(length(title) between 1 and 160), status text not null check(status in ('DRAFT','PLANNING','BLOCKED','CANCELED')), provenance text not null check(provenance in ('MOCK','MOCK_SESSION_MODIFIED','LOCAL_SESSION')), payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,source_idea_id) references public.raxi_ideas(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,external_id));
alter table public.raxi_campaigns enable row level security;
create table public.raxi_strategy_revisions (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, campaign_id uuid not null, revision integer not null check(revision between 1 and 999), status text not null check(status in ('DRAFT','IN_REVIEW','CHANGES_REQUESTED','APPROVED')), payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,campaign_id) references public.raxi_campaigns(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,campaign_id,revision), check((approved_by is null and approved_at is null) or (approved_by is not null and approved_at is not null)));
alter table public.raxi_strategy_revisions enable row level security;
create table public.raxi_strategy_deliverables (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, strategy_id uuid not null, external_id text not null check(length(external_id) between 1 and 128), channel text not null, content_level text not null, format text not null, quantity integer not null check(quantity between 1 and 100), payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), created_at timestamptz not null default now(), foreign key(workspace_id,strategy_id) references public.raxi_strategy_revisions(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,strategy_id,external_id));
alter table public.raxi_strategy_deliverables enable row level security;
create table public.raxi_agent_profiles (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, agent_key text not null check(length(agent_key) between 1 and 128), display_name text not null, role text not null, runtime_status text not null default 'NOT_CONNECTED' check(runtime_status in ('NOT_CONNECTED','CONNECTED','DISABLED')), capability_config jsonb not null default '{}'::jsonb check(jsonb_typeof(capability_config)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id), unique(workspace_id,agent_key));
alter table public.raxi_agent_profiles enable row level security;
create table public.raxi_agent_tasks (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, agent_id uuid, campaign_id uuid, external_id text not null check(length(external_id) between 1 and 128), title text not null, status text not null default 'QUEUED' check(status in ('QUEUED','RUNNING','WAITING','WAITING_APPROVAL','BLOCKED','FAILED','COMPLETED','CANCELED')), input_snapshot jsonb not null default '{}'::jsonb check(jsonb_typeof(input_snapshot)='object'), output_snapshot jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,agent_id) references public.raxi_agent_profiles(workspace_id,id) on delete restrict, foreign key(workspace_id,campaign_id) references public.raxi_campaigns(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,external_id));
alter table public.raxi_agent_tasks enable row level security;
create table public.raxi_agent_events (id bigint generated always as identity primary key, workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, agent_id uuid, task_id uuid, campaign_id uuid, event_type text not null check(length(event_type) between 2 and 128), source_kind text not null check(source_kind in ('HQ_HUMAN','AGENT_EXECUTOR','CODEX_IMPORT','ARIA_MCP','SUPERMEMORY','MOCK')), evidence_status text not null default 'UNVERIFIED' check(evidence_status in ('UNVERIFIED','VERIFIED','REJECTED')), source_ref text, payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object'), occurred_at timestamptz not null, recorded_at timestamptz not null default now(), foreign key(workspace_id,agent_id) references public.raxi_agent_profiles(workspace_id,id) on delete restrict, foreign key(workspace_id,task_id) references public.raxi_agent_tasks(workspace_id,id) on delete restrict, foreign key(workspace_id,campaign_id) references public.raxi_campaigns(workspace_id,id) on delete restrict);
alter table public.raxi_agent_events enable row level security;
create table public.raxi_production_jobs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, campaign_id uuid not null, strategy_id uuid not null, deliverable_id uuid not null, external_job_id text not null check(length(external_job_id) between 1 and 160), provider text not null default 'ARIA_STUDIO' check(provider='ARIA_STUDIO'), model text not null, status text not null check(status in ('AWAITING_APPROVAL','QUEUED','RUNNING','SUCCEEDED','FAILED','TIMED_OUT','CANCELED')), execution_approval text not null default 'PENDING' check(execution_approval in ('PENDING','APPROVED','REJECTED')), approved_by uuid references auth.users(id), approved_at timestamptz, price_ceiling_usd numeric(10,4) check(price_ceiling_usd >= 0), order_snapshot jsonb not null default '{}'::jsonb check(jsonb_typeof(order_snapshot)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,campaign_id) references public.raxi_campaigns(workspace_id,id) on delete restrict, foreign key(workspace_id,strategy_id) references public.raxi_strategy_revisions(workspace_id,id) on delete restrict, foreign key(workspace_id,deliverable_id) references public.raxi_strategy_deliverables(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,external_job_id), check((approved_by is null and approved_at is null) or (approved_by is not null and approved_at is not null)));
alter table public.raxi_production_jobs enable row level security;
create table public.raxi_production_receipts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, job_id uuid not null, state text not null check(state in ('SUCCEEDED','FAILED','TIMED_OUT')), aria_image_id text, image_sha256 text check(image_sha256 ~ '^[0-9a-f]{64}$'), price_usd numeric(10,4) check(price_usd >= 0), provider_payload jsonb not null default '{}'::jsonb check(jsonb_typeof(provider_payload)='object'), verified_source boolean not null default false, received_at timestamptz not null default now(), foreign key(workspace_id,job_id) references public.raxi_production_jobs(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,job_id), unique(workspace_id,aria_image_id));
alter table public.raxi_production_receipts enable row level security;
create table public.raxi_assets (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, parent_asset_id uuid, job_id uuid, external_asset_id text, aria_image_id text, kind text not null default 'ORIGINAL' check(kind in ('ORIGINAL','PREVIEW','REFERENCE','OTHER')), bucket_id text not null default 'raxi-hq-private' check(bucket_id='raxi-hq-private'), object_path text not null, mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp','application/json')), byte_size bigint not null check(byte_size between 1 and 52428800), sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'), qa_status text not null default 'VISUAL_REVIEW_REQUIRED' check(qa_status in ('VISUAL_REVIEW_REQUIRED','PASS','FAIL')), human_decision text not null default 'PENDING' check(human_decision in ('PENDING','APPROVED','REJECTED')), metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,parent_asset_id) references public.raxi_assets(workspace_id,id) on delete restrict, foreign key(workspace_id,job_id) references public.raxi_production_jobs(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,bucket_id,object_path), check(split_part(object_path,'/',1)=workspace_id::text));
alter table public.raxi_assets enable row level security;
create table public.raxi_asset_reviews (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, asset_id uuid not null, review_version integer not null check(review_version between 1 and 999), image_sha256 text not null check(image_sha256 ~ '^[0-9a-f]{64}$'), qa_status text not null check(qa_status in ('VISUAL_REVIEW_REQUIRED','PASS','FAIL')), human_decision text not null default 'PENDING' check(human_decision in ('PENDING','APPROVED','REJECTED')), notes text, reviewer_user_id uuid references auth.users(id), reviewed_at timestamptz, decided_by uuid references auth.users(id), decided_at timestamptz, created_at timestamptz not null default now(), foreign key(workspace_id,asset_id) references public.raxi_assets(workspace_id,id) on delete restrict, unique(workspace_id,id), unique(workspace_id,asset_id,review_version));
alter table public.raxi_asset_reviews enable row level security;
create table public.raxi_approvals (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, subject_kind text not null check(subject_kind in ('IDEA','CAMPAIGN','STRATEGY','JOB','ASSET','PUBLICATION')), subject_id uuid not null, action text not null check(action in ('APPROVED','REJECTED','CHANGES_REQUESTED','CANCELED')), actor_user_id uuid not null references auth.users(id), idempotency_key text not null check(length(idempotency_key) between 1 and 160), context jsonb not null default '{}'::jsonb check(jsonb_typeof(context)='object'), decided_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(workspace_id,id), unique(workspace_id,idempotency_key));
alter table public.raxi_approvals enable row level security;
create table public.raxi_publication_plans (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, campaign_id uuid not null, asset_id uuid, channel text not null, status text not null default 'DRAFT' check(status in ('DRAFT','IN_REVIEW','APPROVED','SCHEDULED','CANCELED','PUBLISHED','FAILED')), scheduled_at timestamptz, content_snapshot jsonb not null default '{}'::jsonb check(jsonb_typeof(content_snapshot)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,campaign_id) references public.raxi_campaigns(workspace_id,id) on delete restrict, foreign key(workspace_id,asset_id) references public.raxi_assets(workspace_id,id) on delete restrict, unique(workspace_id,id));
alter table public.raxi_publication_plans enable row level security;
create table public.raxi_memory_refs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, namespace text not null, memory_id text not null, subject_kind text not null, subject_id text not null, sync_status text not null default 'REFERENCED' check(sync_status in ('REFERENCED','SYNCED','FAILED')), metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'), created_at timestamptz not null default now(), unique(workspace_id,id), unique(workspace_id,namespace,memory_id));
alter table public.raxi_memory_refs enable row level security;
create table public.raxi_audit_events (id bigint generated always as identity primary key, workspace_id uuid not null references public.raxi_workspaces(id) on delete restrict, action text not null check(length(action) between 2 and 160), actor_kind text not null check(actor_kind in ('HUMAN','AGENT','SYSTEM','CODEX')), actor_user_id uuid references auth.users(id), resource_kind text not null, resource_id text, source_ref text, details jsonb not null default '{}'::jsonb check(jsonb_typeof(details)='object'), occurred_at timestamptz not null default now(), recorded_at timestamptz not null default now());
alter table public.raxi_audit_events enable row level security;
