create policy "raxi_workspaces_owner_select" on public.raxi_workspaces for select to authenticated using (owner_user_id = (select auth.uid()));
create policy "raxi_workspaces_owner_insert" on public.raxi_workspaces for insert to authenticated with check (owner_user_id = (select auth.uid()));
create policy "raxi_workspaces_owner_update" on public.raxi_workspaces for update to authenticated using (owner_user_id = (select auth.uid())) with check (owner_user_id = (select auth.uid()));
