insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('raxi-hq-private','raxi-hq-private',false,52428800,array['image/jpeg','image/png','image/webp','application/json']) on conflict(id) do nothing;
create policy "raxi_hq_private_owner_read" on storage.objects for select to authenticated using (
bucket_id = 'raxi-hq-private' and exists (
select 1 from public.raxi_workspaces w where w.id::text = split_part(name,'/',1) and w.owner_user_id = (select auth.uid())
));
